renderSrc:
(h) => {
    h.innerHTML = `<div class="row"><label>搜索到 N <input type="number" id="nt01_n" value="10000" min="100"></label><button class="primary" id="nt01_run">找完美数</button></div><div id="nt01_out" class="sequence" style="margin-top:12px;">点"找完美数"</div>`;
    document.getElementById('nt01_run').onclick = () => {
      const N = +document.getElementById('nt01_n').value;
      const out = [];
      for (let n = 2; n <= N; n++) {
        const s = properDivisors(n).reduce((a, b) => a + b, 0);
        if (s === n) out.push(n);
      }
      document.getElementById('nt01_out').innerHTML = out.length > 0
        ? out.map(n => `<strong>${n}</strong> = ${properDivisors(n).join(' + ')}`).join('  ·  ')
        : 'N 范围内没找到（已知前 5 个：6, 28, 496, 8128, 33550336）';
    };
  }

(h) => {
    h.innerHTML = `<div class="row"><label>搜索到 N <input type="number" id="nt02_n" value="5000" min="100"></label><button class="primary" id="nt02_run">找亲和对</button></div><div id="nt02_out" class="sequence" style="margin-top:12px;"></div>`;
    document.getElementById('nt02_run').onclick = () => {
      const N = +document.getElementById('nt02_n').value;
      const s = {};
      for (let i = 1; i <= N; i++) s[i] = properDivisors(i).reduce((a, b) => a + b, 0);
      const pairs = [];
      for (let i = 2; i <= N; i++) {
        const j = s[i];
        if (j > i && j <= N && s[j] === i) pairs.push([i, j]);
      }
      document.getElementById('nt02_out').innerHTML = pairs.length > 0
        ? pairs.map(([a, b]) => `<strong>(${a}, ${b})</strong>`).join('  ·  ')
        : `N 范围内没找到。最小对：(220, 284)、(1184, 1210)、(2620, 2924)...`;
    };
  }

(h) => {
    h.innerHTML = `<div class="row"><label>扫描到 N <input type="number" id="nt03_n" value="50" min="10"></label><button class="primary" id="nt03_run">分类</button></div><div id="nt03_out" class="sequence" style="margin-top:12px;"></div>`;
    document.getElementById('nt03_run').onclick = () => {
      const N = +document.getElementById('nt03_n').value;
      const lines = [];
      for (let n = 2; n <= N; n++) {
        const s = properDivisors(n).reduce((a, b) => a + b, 0);
        let cls = s < n ? '亏' : s === n ? '<strong>完</strong>' : '过';
        lines.push(`${n}: σ=${s} → ${cls}`);
      }
      document.getElementById('nt03_out').innerHTML = lines.join(' · ');
    };
  }

(h) => {
    h.innerHTML = `<div class="row"><label>扫描到 N <input type="number" id="nt04_n" value="100000" min="100"></label><button class="primary" id="nt04_run">找自恋数</button></div><div id="nt04_out" class="sequence" style="margin-top:12px;"></div>`;
    document.getElementById('nt04_run').onclick = () => {
      const N = +document.getElementById('nt04_n').value;
      const out = [];
      for (let n = 1; n <= N; n++) {
        const ds = String(n).split('').map(Number);
        const k = ds.length;
        const s = ds.reduce((a, d) => a + Math.pow(d, k), 0);
        if (s === n) out.push(n);
      }
      document.getElementById('nt04_out').innerHTML = out.length > 0
        ? out.map(n => {
            const ds = String(n).split('').map(Number);
            const k = ds.length;
            return `<strong>${n}</strong> = ${ds.map(d => d + '<sup>' + k + '</sup>').join('+')}`;
          }).join('  ·  ')
        : 'N 范围内没找到';
    };
  }

(h) => {
    h.innerHTML = `<div class="row"><label>输入 n <input type="number" id="nt05_n" value="19" min="1"></label><button class="primary" id="nt05_run">判断</button></div><div id="nt05_seq" class="sequence" style="margin-top:12px;"></div><div id="nt05_out" class="stat" style="margin-top:12px;"><div class="k">判定</div><div class="v">—</div></div>`;
    document.getElementById('nt05_run').onclick = () => {
      const n = +document.getElementById('nt05_n').value;
      const seen = new Set();
      let cur = n;
      const path = [cur];
      while (cur !== 1 && !seen.has(cur)) {
        seen.add(cur);
        cur = String(cur).split('').reduce((a, d) => a + d * d, 0);
        path.push(cur);
      }
      document.getElementById('nt05_seq').textContent = path.slice(0, 30).join(' → ') + (path.length > 30 ? ' ...' : '');
      const v = document.querySelector('#nt05_out .v');
      v.textContent = cur === 1 ? '✓ 快乐数' : '✗ 不快乐数（进入循环）';
      v.style.color = cur === 1 ? 'var(--good)' : 'var(--warn)';
    };
  }

(h) => {
    h.innerHTML = `<div class="row"><label>扫描到 N <input type="number" id="nt06_n" value="200" min="10"></label><button class="primary" id="nt06_run">找</button></div><div id="nt06_out" class="sequence" style="margin-top:12px;"></div>`;
    document.getElementById('nt06_run').onclick = () => {
      const N = +document.getElementById('nt06_n').value;
      const out = [];
      for (let n = 1; n <= N; n++) {
        const s = sumDigits(n);
        if (n % s === 0) out.push(n);
      }
      document.getElementById('nt06_out').innerHTML = out.join(', ');
    };
  }

(h) => {
    h.innerHTML = `<div class="row"><label>输入 4 位数 <input type="number" id="nt07_n" value="3524" min="1000" max="9999"></label><button class="primary" id="nt07_run">变换</button></div><div id="nt07_seq" class="sequence" style="margin-top:12px;"></div>`;
    document.getElementById('nt07_run').onclick = () => {
      let n = +document.getElementById('nt07_n').value;
      if (n < 1000 || n > 9999 || new Set(String(n)).size === 1) {
        document.getElementById('nt07_seq').textContent = '请输入 4 位数（且不全相同）';
        return;
      }
      const path = [n];
      while (n !== 6174) {
        const ds = String(n).padStart(4, '0').split('').map(Number);
        const asc = parseInt(ds.slice().sort((a, b) => a - b).join(''));
        const desc = parseInt(ds.slice().sort((a, b) => b - a).join(''));
        n = desc - asc;
        path.push(n);
        if (path.length > 20) break;
      }
      document.getElementById('nt07_seq').textContent = path.join(' → ');
    };
  }

(h) => {
    h.innerHTML = `<div class="row"><label>输入 n <input type="number" id="nt08_n" value="87" min="1"></label><button class="primary" id="nt08_run">迭代</button></div><div id="nt08_seq" class="sequence" style="margin-top:12px;"></div><div id="nt08_out" class="stat" style="margin-top:12px;"><div class="k">步数</div><div class="v">—</div></div>`;
    document.getElementById('nt08_run').onclick = () => {
      let n = +document.getElementById('nt08_n').value;
      const path = [n];
      const rev = x => +String(x).split('').reverse().join('');
      const isPal = x => String(x) === String(x).split('').reverse().join('');
      let steps = 0;
      while (!isPal(n) && steps < 50) {
        n = n + rev(n);
        path.push(n);
        steps++;
      }
      document.getElementById('nt08_seq').textContent = path.slice(0, 15).join(' → ') + (path.length > 15 ? ' ...' : '');
      document.querySelector('#nt08_out .v').textContent = steps;
    };
  }

(h) => {
    h.innerHTML = `<div class="row"><label>扫描到 N <input type="number" id="nt09_n" value="10000" min="1000"></label><button class="primary" id="nt09_run">找</button><span id="nt09_status" style="color: var(--muted); font-size: 13px;"></span></div><div id="nt09_out" class="sequence" style="margin-top:12px;"></div>`;
    document.getElementById('nt09_run').onclick = () => {
      const N = +document.getElementById('nt09_n').value;
      document.getElementById('nt09_status').textContent = '扫描中…';
      setTimeout(() => {
        const out = [];
        for (let n = 561; n <= N; n += 2) {
          if (isPrimeSmall(n)) continue;
          let ok = true;
          for (let b = 2; b <= Math.min(n-1, 100) && ok; b++) {
            if (gcd(b, n) === 1) {
              let r = 1; for (let i = 0; i < n - 1; i++) r = (r * b) % n;
              if (r !== 1) ok = false;
            }
          }
          if (ok) out.push(n);
        }
        document.getElementById('nt09_out').innerHTML = out.length > 0
          ? out.map(n => `<strong>${n}</strong> = ${factorize(n).join('×')}`).join('  ·  ')
          : 'N 范围内没找到';
        document.getElementById('nt09_status').textContent = `找到 ${out.length} 个`;
      }, 50);
    };
  }

(h) => {
    h.innerHTML = `<div class="row"><label>扫描到 N <input type="number" id="nt10_n" value="2000" min="100"></label><button class="primary" id="nt10_run">找</button></div><div id="nt10_out" class="sequence" style="margin-top:12px;"></div>`;
    document.getElementById('nt10_run').onclick = () => {
      const N = +document.getElementById('nt10_n').value;
      const out = [];
      for (let n = 4; n <= N; n++) {
        if (isPrimeSmall(n)) continue;
        const fs = factorize(n);
        const sSelf = sumDigits(n);
        const sFac = fs.reduce((a, p) => a + sumDigits(p), 0);
        if (sSelf === sFac) out.push(n);
      }
      document.getElementById('nt10_out').innerHTML = out.length > 0
        ? out.map(n => `<strong>${n}</strong> = ${factorize(n).join('×')}`).join('  ·  ')
        : 'N 范围内没找到';
    };
  }

(h) => {
    h.innerHTML = `<div class="row"><label>扫描到 N <input type="number" id="nt11_n" value="100000" min="1000"></label><button class="primary" id="nt11_run">找</button></div><div id="nt11_out" class="sequence" style="margin-top:12px;"></div>`;
    document.getElementById('nt11_run').onclick = () => {
      const N = +document.getElementById('nt11_n').value;
      const out = [];
      for (let n = 1000; n <= N; n++) {
        if (String(n).length % 2 !== 0) continue;
        const ns = String(n);
        const half = ns.length / 2;
        const sorted = ns.split('').sort().join('');
        for (let a = 10; a < Math.sqrt(n); a++) {
          if (n % a !== 0) continue;
          const b = n / a;
          if (String(a).length !== half || String(b).length !== half) continue;
          if (String(a).endsWith('0') && String(b).endsWith('0')) continue;
          const aStr = String(a), bStr = String(b);
          if ((aStr + bStr).split('').sort().join('') === sorted) {
            out.push([n, a, b]);
            break;
          }
        }
      }
      document.getElementById('nt11_out').innerHTML = out.length > 0
        ? out.map(([n, a, b]) => `<strong>${n}</strong> = ${a} × ${b}`).join('  ·  ')
        : 'N 范围内没找到';
    };
  }

(h) => {
    h.innerHTML = `<div class="row"><label>n <input type="number" id="nt12_n" value="10" min="1"></label><button class="primary" id="nt12_run">生成</button></div><div id="nt12_out" class="sequence" style="margin-top:12px;"></div>`;
    document.getElementById('nt12_run').onclick = () => {
      const n = +document.getElementById('nt12_n').value;
      const out = [];
      for (let i = 1; i <= n; i++) out.push(i * (i+1) / 2);
      document.getElementById('nt12_out').innerHTML = out.join(', ');
    };
  }

(h) => {
    h.innerHTML = `<div class="row"><label>n <input type="number" id="nt13_n" value="10" min="1"></label><button class="primary" id="nt13_run">生成</button></div><div id="nt13_out" class="sequence" style="margin-top:12px;"></div>`;
    document.getElementById('nt13_run').onclick = () => {
      const n = +document.getElementById('nt13_n').value;
      const out = [];
      for (let i = 1; i <= n; i++) out.push(i * (i+1) * (i+2) / 6);
      document.getElementById('nt13_out').innerHTML = out.join(', ');
    };
  }

(h) => {
    h.innerHTML = `<div class="row"><label>输入 n <input type="number" id="nt14_n" value="12345"></label><button class="primary" id="nt14_run">求根</button></div><div id="nt14_seq" class="sequence" style="margin-top:12px;"></div><div id="nt14_out" class="stat" style="margin-top:12px;"><div class="k">数字根</div><div class="v">—</div></div>`;
    document.getElementById('nt14_run').onclick = () => {
      const n = +document.getElementById('nt14_n').value;
      const path = [n];
      let cur = n;
      while (cur >= 10) {
        cur = sumDigits(cur);
        path.push(cur);
      }
      document.getElementById('nt14_seq').textContent = path.join(' → ');
      document.querySelector('#nt14_out .v').textContent = cur;
    };
  }

(h) => {
    h.innerHTML = `<div class="row"><label>扫描到 N <input type="number" id="nt15_n" value="10000" min="100"></label><button class="primary" id="nt15_run">找</button></div><div id="nt15_out" class="sequence" style="margin-top:12px;"></div>`;
    document.getElementById('nt15_run').onclick = () => {
      const N = +document.getElementById('nt15_n').value;
      const out = [];
      for (let n = 2; n <= N; n++) {
        if (!isPrimeSmall(n)) continue;
        const s = String(n);
        if (s === s.split('').reverse().join('')) out.push(n);
      }
      document.getElementById('nt15_out').innerHTML = out.join(', ');
    };
  }

(h) => {
    h.innerHTML = `<div class="row"><label>扫描到 N <input type="number" id="nt16_n" value="500" min="100"></label><button class="primary" id="nt16_run">算间隙</button></div><div id="nt16_out" class="sequence" style="margin-top:12px;"></div><div id="nt16_max" class="stat" style="margin-top:12px;"><div class="k">最大间隙</div><div class="v">—</div></div>`;
    document.getElementById('nt16_run').onclick = () => {
      const N = +document.getElementById('nt16_n').value;
      const gaps = [];
      let prev = 2;
      for (let n = 3; n <= N; n++) {
        if (isPrimeSmall(n)) {
          gaps.push([prev, n, n - prev]);
          prev = n;
        }
      }
      document.getElementById('nt16_out').innerHTML = gaps.map(([a, b, g]) => `${b}-${a}=${g}`).join(' · ');
      let maxG = 0, maxA = 0, maxB = 0;
      for (const [a, b, g] of gaps) if (g > maxG) { maxG = g; maxA = a; maxB = b; }
      document.querySelector('#nt16_max .v').textContent = `${maxG}（在 ${maxA} 和 ${maxB} 之间）`;
    };
  }

(h) => {
    h.innerHTML = `<div class="row"><label>模数 m <input type="number" id="nt17_m" value="7" min="2" max="100"></label><label>范围 N <input type="number" id="nt17_n" value="50" min="10"></label><button class="primary" id="nt17_run">画</button></div><div id="nt17_out" class="sequence" style="margin-top:12px;"></div>`;
    document.getElementById('nt17_run').onclick = () => {
      const m = +document.getElementById('nt17_m').value;
      const N = +document.getElementById('nt17_n').value;
      const out = [];
      for (let n = 0; n <= N; n++) out.push(n % m);
      document.getElementById('nt17_out').innerHTML = out.map((r, i) => `${i}→${r}`).join(' · ');
    };
  }

(h) => {
    h.innerHTML = `<div class="row"><label>输入 n <input type="number" id="nt18_n" value="36" min="2"></label><button class="primary" id="nt18_run">算 φ</button></div><div id="nt18_out" class="sequence" style="margin-top:12px;"></div>`;
    document.getElementById('nt18_run').onclick = () => {
      const n = +document.getElementById('nt18_n').value;
      const coprime = [];
      for (let i = 1; i <= n; i++) if (gcd(i, n) === 1) coprime.push(i);
      document.getElementById('nt18_out').innerHTML = `φ(${n}) = <strong>${coprime.length}</strong><br>互素数：${coprime.join(', ')}<br>分解：${n} = ${factorize(n).join('×')}`;
    };
  }

(h) => {
    h.innerHTML = `<div class="row"><label>指数 p 上限 <input type="number" id="nt19_p" value="60" min="2"></label><button class="primary" id="nt19_run">找</button></div><div id="nt19_out" class="sequence" style="margin-top:12px;"></div>`;
    document.getElementById('nt19_run').onclick = () => {
      const P = +document.getElementById('nt19_p').value;
      const out = [];
      for (let p = 2; p <= P; p++) {
        if (!isPrimeSmall(p)) continue;
        const m = Math.pow(2, p) - 1;
        // 用 BigInt 防止溢出
        let mBig = 1n;
        for (let i = 0; i < p; i++) mBig *= 2n;
        mBig -= 1n;
        let isPrimeBig = true;
        // 简单素性测试（对 2^p - 1 用 Miller-Rabin 太复杂，只测到 sqrt 较慢）
        // 改用：isPrimeSmall 对 number，若 > 2^31 用 BigInt 简单测
        if (mBig < 1000000n) {
          if (!isPrimeSmall(Number(mBig))) isPrimeBig = false;
        } else {
          // 大数：试除到 1000
          for (let d = 2; d * d <= Number(mBig > 1000000000n ? 100000 : Number(mBig)); d++) {
            if (mBig % BigInt(d) === 0n) { isPrimeBig = false; break; }
          }
        }
        if (isPrimeBig) out.push({ p, m: mBig.toString() });
      }
      document.getElementById('nt19_out').innerHTML = out.length > 0
        ? out.map(x => `<strong>2<sup>${x.p}</sup> - 1 = ${x.m}</strong>`).join('  ·  ')
        : 'p 上限内没找到';
    };
  }

(h) => {
    h.innerHTML = `<div class="row"><label>偶数 N <input type="number" id="nt20_n" value="100" min="4" max="10000"></label><button class="primary" id="nt20_run">拆</button></div><div id="nt20_out" class="sequence" style="margin-top:12px;"></div>`;
    document.getElementById('nt20_run').onclick = () => {
      const N = +document.getElementById('nt20_n').value;
      if (N % 2 !== 0) { document.getElementById('nt20_out').textContent = '请输入偶数'; return; }
      const pairs = [];
      for (let p = 2; p <= N/2; p++) {
        if (isPrimeSmall(p) && isPrimeSmall(N - p)) pairs.push([p, N - p]);
      }
      document.getElementById('nt20_out').innerHTML = pairs.length > 0
        ? pairs.map(([a, b]) => `<strong>${a} + ${b}</strong>`).join('  ·  ')
        : `反例：${N} 不能写成两素数之和`;
    };
  }

(h) => {
    h.innerHTML = `<div class="row"><label>项数 n <input type="number" id="sq01_n" value="20" min="1"></label><button class="primary" id="sq01_run">生成</button></div><div id="sq01_out" class="sequence" style="margin-top:12px;"></div>`;
    document.getElementById('sq01_run').onclick = () => {
      const n = +document.getElementById('sq01_n').value;
      const out = [];
      let a = 1, b = 1;
      for (let i = 0; i < n; i++) { out.push(a); [a, b] = [b, a + b]; }
      document.getElementById('sq01_out').innerHTML = out.join(', ');
    };
  }

(h) => {
    h.innerHTML = `<div class="row"><label>项数 n <input type="number" id="sq02_n" value="20" min="2"></label><button class="primary" id="sq02_run">比值</button></div><div id="sq02_out" class="sequence" style="margin-top:12px;"></div>`;
    document.getElementById('sq02_run').onclick = () => {
      const n = +document.getElementById('sq02_n').value;
      const phi = (1 + Math.sqrt(5)) / 2;
      const ratios = [];
      let a = 1, b = 1;
      for (let i = 1; i < n; i++) { ratios.push((b / a).toFixed(8)); [a, b] = [b, a + b]; }
      document.getElementById('sq02_out').innerHTML = ratios.map((r, i) => `F${i+2}/F${i+1} = ${r}`).join('<br>') + `<br><br>真实 φ = ${phi.toFixed(10)}`;
    };
  }

(h) => {
    h.innerHTML = `<div class="row"><label>项数 n <input type="number" id="sq03_n" value="15" min="1"></label><button class="primary" id="sq03_run">生成</button></div><div id="sq03_out" class="sequence" style="margin-top:12px;"></div>`;
    document.getElementById('sq03_run').onclick = () => {
      const n = +document.getElementById('sq03_n').value;
      const out = [];
      let a = 1, b = 3;
      for (let i = 0; i < n; i++) { out.push(a); [a, b] = [b, a + b]; }
      document.getElementById('sq03_out').innerHTML = out.join(', ');
    };
  }

(h) => {
    h.innerHTML = `<div class="row"><label>项数 n <input type="number" id="sq04_n" value="10" min="1"></label><button class="primary" id="sq04_run">生成</button></div><div id="sq04_out" class="sequence" style="margin-top:12px;"></div>`;
    document.getElementById('sq04_run').onclick = () => {
      const n = +document.getElementById('sq04_n').value;
      const out = [];
      for (let i = 0; i < n; i++) {
        out.push(factorial(2 * i) / factorial(i) / factorial(i) / (i + 1));
      }
      document.getElementById('sq04_out').innerHTML = out.join(', ');
    };
  }

(h) => {
    h.innerHTML = `<div class="row"><label>项数 n <input type="number" id="sq05_n" value="8" min="1" max="10"></label><button class="primary" id="sq05_run">生成</button></div><div id="sq05_out" class="sequence" style="margin-top:12px;"></div>`;
    document.getElementById('sq05_run').onclick = () => {
      const n = +document.getElementById('sq05_n').value;
      // Bell triangle
      const B = [[1]];
      for (let i = 1; i < n; i++) {
        const row = [B[i-1][i-1]];
        for (let j = 1; j <= i; j++) row.push(row[j-1] + B[i-1][j-1]);
        B.push(row);
      }
      const out = B.map(r => r[0]);
      document.getElementById('sq05_out').innerHTML = out.join(', ');
    };
  }

(h) => {
    h.innerHTML = `<div class="row"><label>项数 n <input type="number" id="sq06_n" value="8" min="1" max="10"></label><button class="primary" id="sq06_run">生成</button></div><div id="sq06_out" class="sequence" style="margin-top:12px;"></div>`;
    document.getElementById('sq06_run').onclick = () => {
      const n = +document.getElementById('sq06_n').value;
      const D = [1, 0];
      for (let i = 2; i <= n; i++) D.push((i - 1) * (D[i-1] + D[i-2]));
      document.getElementById('sq06_out').innerHTML = D.join(', ');
    };
  }

(h) => {
    h.innerHTML = `<div class="row"><label>n <input type="number" id="sq07_n" value="6" min="1" max="10"></label><button class="primary" id="sq07_run">画</button></div><div id="sq07_out" style="margin-top:12px; font-family: monospace; line-height: 1.6;"></div>`;
    document.getElementById('sq07_run').onclick = () => {
      const n = +document.getElementById('sq07_n').value;
      const lines = [];
