      const p = Array.from({ length: N + 1 }, () => new Array(N + 1).fill(0));
      p[0][0] = 1;
      for (let k = 1; k <= N; k++) {
        for (let n = 0; n <= N; n++) {
          p[n][k] = p[n][k-1] + (n >= k ? p[n-k][k] : 0);
