(h) => {
    h.innerHTML = `<div class="row" style="margin-bottom: 8px;">
      <label>城市数 n <input type="number" id="gr02_n" value="6" min="3" max="10"></label>
      <button class="primary" id="gr02_bf">暴力（精确）</button>
      <button class="primary" id="gr02_nn">贪心（最近邻）</button>
      <button class="ghost" id="gr02_same">同一组数据</button>
      <span id="gr02_status" style="color: var(--muted); font-size: 13px;"></span>
    </div>
    <div id="gr02_out" class="sequence" style="margin-top:12px;"></div>
    <div id="gr02_compare" style="margin-top: 12px;"></div>`;
    let d = null;
    function genDists(n) {
      const dd = Array.from({ length: n }, () => Array.from({ length: n }, () => Math.floor(Math.random() * 100)));
      for (let i = 0; i < n; i++) dd[i][i] = 0;
      // 对称
      for (let i = 0; i < n; i++) for (let j = i+1; j < n; j++) dd[j][i] = dd[i][j];
      return dd;
    }
    function pathDist(path, dd) {
      let s = 0;
      for (let i = 0; i < path.length - 1; i++) s += dd[path[i]][path[i+1]];
      return s;
    }
    function bruteForce(dd) {
      const n = dd.length;
      const perm = Array.from({ length: n - 1 }, (_, i) => i + 1);
      let bestDist = Infinity, bestPath = null;
      const permute = (arr, l, r) => {
        if (l === r) {
          const path = [0, ...arr, 0];
          const dist = pathDist(path, dd);
          if (dist < bestDist) { bestDist = dist; bestPath = path; }
          return;
        }
        for (let i = l; i <= r; i++) {
          [arr[l], arr[i]] = [arr[i], arr[l]];
          permute(arr, l + 1, r);
          [arr[l], arr[i]] = [arr[i], arr[l]];
        }
      };
      permute(perm, 0, perm.length - 1);
      return { path: bestPath, dist: bestDist, count: factorial(n-1) };
    }
    function nearestNeighbor(dd) {
      const n = dd.length;
      const visited = new Set([0]);
      const path = [0];
      let cur = 0;
      let total = 0;
      while (visited.size < n) {
        let best = -1, bestD = Infinity;
        for (let j = 0; j < n; j++) {
          if (visited.has(j)) continue;
          if (dd[cur][j] < bestD) { bestD = dd[cur][j]; best = j; }
        }
        path.push(best); visited.add(best); total += bestD; cur = best;
      }
      path.push(0);
      total += dd[cur][0];
      return { path, dist: total, count: 0 };
    }
    function renderResult(name, res, dd) {
      // 显示距离矩阵
      const matHtml = '<details><summary>距离矩阵</summary><pre style="font-size: 11px;">' +
        dd.map(row => row.map(v => String(v).padStart(4, ' ')).join(' ')).join('\n') + '</pre></details>';
      return `<strong>${name}：</strong>路径 = ${res.path.join(' → ')}，距离 = <strong>${res.dist}</strong>${res.count > 0 ? `（检查 ${res.count} 个排列）` : ''}<br>${matHtml}`;
    }
    document.getElementById('gr02_bf').onclick = () => {
      const n = +document.getElementById('gr02_n').value;
      if (n > 9) { alert('n>9 暴力太慢，请用贪心或减少 n'); return; }
      d = genDists(n);
      document.getElementById('gr02_status').textContent = '暴力搜索中…';
      setTimeout(() => {
        const r = bruteForce(d);
        document.getElementById('gr02_out').innerHTML = renderResult('暴力（精确）', r, d);
        document.getElementById('gr02_status').textContent = `完成，检查 ${r.count} 个排列`;
        document.getElementById('gr02_compare').innerHTML = '';
      }, 50);
    };
    document.getElementById('gr02_nn').onclick = () => {
      const n = +document.getElementById('gr02_n').value;
      d = genDists(n);
      const r = nearestNeighbor(d);
      document.getElementById('gr02_out').innerHTML = renderResult('贪心（最近邻）', r, d);
      document.getElementById('gr02_status').textContent = '完成（贪心是 O(n²)）';
      document.getElementById('gr02_compare').innerHTML = '';
    };
