      const r1 = nearestNeighbor(d);
      const r2 = bruteForce(d);
      const ratio = (r1.dist / r2.dist * 100).toFixed(1);
      document.getElementById('gr02_compare').innerHTML =
        `<strong>同一组数据对比：</strong><br>暴力（精确）: 距离 = <strong>${r2.dist}</strong><br>贪心（近似）: 距离 = <strong>${r1.dist}</strong>，比最优差 <strong>${ratio}%</strong>`;
    };
  }

