      const preT = r => { if (r < 0) return; pre.push(r); preT(left[r]); preT(right[r]); };
      const inoT = r => { if (r < 0) return; inoT(left[r]); ino.push(r); inoT(right[r]); };
      const postT = r => { if (r < 0) return; postT(left[r]); postT(right[r]); post.push(r); };
