(h) => {
    h.innerHTML = `<div class="row"><label>4 个数字（逗号分隔）<input type="text" id="al01_n" value="1,5,5,5"></label><button class="primary" id="al01_run">解</button></div><div id="al01_out" class="sequence" style="margin-top:12px;"></div>`;
    document.getElementById('al01_run').onclick = () => {
      const nums = document.getElementById('al01_n').value.split(',').map(Number);
      const eps = 1e-6;
      // 暴力枚举：所有 (a op b) op (c op d) 和 ((a op b) op c) op d 等排列
      const perms = [[nums[0], nums[1], nums[2], nums[3]]];
      const swap = (arr, i, j) => { const t = arr[i]; arr[i] = arr[j]; arr[j] = t; };
      const gen = (arr, l) => {
        if (l === arr.length - 1) { perms.push([...arr]); return; }
        for (let i = l; i < arr.length; i++) { swap(arr, l, i); gen(arr, l + 1); swap(arr, l, i); }
      };
      gen([...nums], 0);
      const ops = [(a, b) => a + b, (a, b) => a - b, (a, b) => a * b, (a, b) => b !== 0 ? a / b : null];
      const opName = ['+', '-', '×', '÷'];
      const apply = (a, b, op) => { const r = ops[op](a, b); return r === null ? null : Math.abs(r) > 1e10 ? null : r; };
      const found = [];
      for (const p of perms) {
        for (let o1 = 0; o1 < 4; o1++) for (let o2 = 0; o2 < 4; o2++) for (let o3 = 0; o3 < 4; o3++) {
          // 5 种括法
          const trials = [
            [apply(p[0], p[1], o1), apply(p[2], p[3], o2), o3],
            [apply(apply(p[0], p[1], o1), p[2], o2), p[3], o3],
            [p[0], apply(p[1], p[2], o2), apply(apply(p[0], apply(p[1], p[2], o2), o3), p[3])],
          ];
          for (const [a, b, op] of trials) {
            if (a === null || b === null) continue;
            const r = apply(a, b, op);
            if (r !== null && Math.abs(r - 24) < eps) {
              found.push(`(${p[0]}${opName[o1]}${p[1]})${opName[o3] ?? ''}(${p[2]}${opName[o2]}${p[3]})`);
            }
          }
        }
      }
      const uniq = [...new Set(found)];
      document.getElementById('al01_out').innerHTML = uniq.length > 0
        ? `找到 ${uniq.length} 个解：<br>${uniq.slice(0, 5).join('<br>')}`
        : '无解';
    };
  }

