    function nimXor(arr) { return arr.reduce((a, b) => a ^ b, 0); }
    function aiMove() {
      const x = nimXor(piles);
      if (x === 0) {
        // 必输状态：随便取一颗
        for (let i = 0; i < piles.length; i++) if (piles[i] > 0) { return [i, 1]; }
        return null;
      }
      // 找使异或变 0 的步
      for (let i = 0; i < piles.length; i++) {
