      logEl.innerHTML = logEl.innerHTML === '' ? text : logEl.innerHTML + '<br>' + text;
    }
    function checkWinner() {
      if (piles.every(p => p === 0)) {
        gameOver = true;
        return turn === 0 ? 'AI 胜！' : '你胜！';
      }
      return null;
    }
    function render() {
