      if (gameOver) {
        ctrlEl.innerHTML = '<em>游戏结束，点"新游戏"再来</em>';
        stateEl.textContent = '🎉 ' + (turn === 0 ? 'AI 胜！' : '你胜！');
        stateEl.style.color = turn === 0 ? 'var(--warn)' : 'var(--good)';
        return;
      }
      const x = nimXor(piles);
      if (turn === 0) {
        stateEl.textContent = `你走（异或 = ${x}）`;
        stateEl.style.color = x === 0 ? 'var(--warn)' : 'var(--good)';
        ctrlEl.innerHTML = `<div class="row"><label>选堆 <select id="al02_pileSel" style="font-size: 14px; padding: 6px;">${piles.map((p, i) => `<option value="${i}" ${p === 0 ? 'disabled' : ''}>堆 ${i+1} (剩 ${p})</option>`).join('')}</select></label><label>取几个 <input type="number" id="al02_take" value="1" min="1" max="9"></label><button class="primary" id="al02_go">我走</button></div>`;
        document.getElementById('al02_go').onclick = () => {
