          let k = +document.getElementById('al02_take').value;
          if (i === undefined || isNaN(i) || piles[i] === 0) { alert('这堆空了'); return; }
          if (isNaN(k) || k < 1) { alert('至少取 1 个'); return; }
          if (k > piles[i]) { alert(`最多取 ${piles[i]} 个`); return; }
          piles[i] -= k;
          appendLog(`你：从堆 ${i+1} 取 ${k} 个 → 剩 [${piles.join(', ')}]`);
          const win = checkWinner();
          if (win) { render(); return; }
          turn = 1;
          render();
        };
      } else {
        stateEl.textContent = `AI 思考中...（异或 = ${x}）`;
        stateEl.style.color = 'var(--muted)';
        ctrlEl.innerHTML = '<em>AI 自动走棋...</em>';
        setTimeout(() => {
          if (gameOver) return;
          const m = aiMove();
          if (m) {
            const [i, k] = m;
            piles[i] -= k;
            appendLog(`AI：从堆 ${i+1} 取 ${k} 个 → 剩 [${piles.join(', ')}]`);
          }
          const win = checkWinner();
          if (win) { render(); return; }
          turn = 0;
          render();
        }, 600);
      }
    }
    function newGame() {
      const n = +document.getElementById('al02_n').value;
      const max = +document.getElementById('al02_max').value;
