(h) => {
    h.innerHTML = `<div class="row"><label>n <input type="number" id="al05_n" value="8" min="4" max="10"></label><button class="primary" id="al05_run">枚举解</button><span id="al05_status" style="color: var(--muted); font-size: 13px;"></span></div><div id="al05_out" class="sequence" style="margin-top:12px;"></div>`;
    document.getElementById('al05_run').onclick = () => {
      const n = +document.getElementById('al05_n').value;
      const sols = [];
      const col = new Set(), d1 = new Set(), d2 = new Set();
      const place = (row, queens) => {
        if (row === n) { sols.push([...queens]); return; }
        for (let c = 0; c < n; c++) {
          if (col.has(c) || d1.has(row - c) || d2.has(row + c)) continue;
          col.add(c); d1.add(row - c); d2.add(row + c);
          queens.push(c);
          place(row + 1, queens);
          queens.pop();
          col.delete(c); d1.delete(row - c); d2.delete(row + c);
        }
      };
      place(0, []);
      document.getElementById('al05_status').textContent = `${n} 皇后共 ${sols.length} 个解`;
      // 显示前 4 个解
      const lines = sols.slice(0, 4).map((s, idx) => {
        const grid = [];
        for (let r = 0; r < n; r++) {
          let row = '|';
          for (let c = 0; c < n; c++) row += (c === s[r] ? '♛' : '·') + '|';
          grid.push(row);
        }
        return `解 ${idx + 1}: ${s.map((c, i) => `第${i+1}行→第${c+1}列`).join(', ')}<br>${grid.join('<br>')}`;
      });
      document.getElementById('al05_out').innerHTML = lines.join('<br><br>');
    };
  }

