      const koch = (x1, y1, x2, y2, d) => {
        if (d === 0) { ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke(); return; }
        const dx = (x2 - x1) / 3, dy = (y2 - y1) / 3;
        const a = [x1, y1], b = [x1 + dx, y1 + dy];
        const c = [x1 + 2*dx, y1 + 2*dy], d2 = [x2, y2];
        // 凸出点
        const peakX = b[0] + (dx - dy * Math.sqrt(3) / 2);
        const peakY = b[1] + (dy + dx * Math.sqrt(3) / 2);
        koch(a[0], a[1], b[0], b[1], d - 1);
        koch(b[0], b[1], peakX, peakY, d - 1);
        koch(peakX, peakY, c[0], c[1], d - 1);
        koch(c[0], c[1], d2[0], d2[1], d - 1);
      };
      // 画等边三角形，每条边做 Koch
      const h = 300, side = 350;
      const x1 = 25, y1 = 340, x2 = x1 + side, y2 = 340, x3 = x1 + side / 2, y3 = 340 - side * Math.sqrt(3) / 2;
      koch(x1, y1, x2, y2, depth);
      koch(x2, y2, x3, y3, depth);
      koch(x3, y3, x1, y1, depth);
    };
  }

