(h) => {
    h.innerHTML = `<div class="row" style="margin-bottom: 8px;">
      <label>难度 <select id="ot08_diff" style="font-size: 14px; padding: 6px;">
        <option value="easy">简单（AI 随机 50% 走）</option>
        <option value="medium">中等（minimax 深度 2）</option>
        <option value="hard" selected>困难（满深度 minimax）</option>
      </select></label>
      <button class="primary small" id="ot08_first" style="font-size: 12px;">AI 先手</button>
      <button class="ghost small" id="ot08_reset">重置</button>
    </div>
    <div id="ot08_status" style="margin-bottom: 8px; font-weight: 600;">你（X）vs AI（O）。你下。</div>
    <div id="ot08_board" style="display: inline-grid; grid-template-columns: repeat(3, 80px); gap: 4px;"></div>
    <div id="ot08_stat" class="row" style="margin-top: 12px; gap: 16px;">
      <div class="stat" style="flex:1;"><div class="k">你胜</div><div class="v" id="ot08_youWins" style="font-size: 18px;">0</div></div>
      <div class="stat" style="flex:1;"><div class="k">平局</div><div class="v" id="ot08_draws" style="font-size: 18px;">0</div></div>
      <div class="stat" style="flex:1;"><div class="k">AI 胜</div><div class="v" id="ot08_aiWins" style="font-size: 18px;">0</div></div>
    </div>`;
    const cv = document.getElementById('ot08_board');
    const status = document.getElementById('ot08_status');
    const diffEl = document.getElementById('ot08_diff');
    let board = Array(9).fill(null);
    let aiTurn = false;
    let youFirst = true;
    let stats = { you: 0, draw: 0, ai: 0 };
    const wins = [[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];
    const checkWin = b => {
      for (const [a, b1, c] of wins) if (b[a] && b[a] === b[b1] && b[a] === b[c]) return b[a];
      return b.every(x => x) ? 'T' : null;
    };
    // 满深度 minimax
    const minimax = (b, isMax) => {
      const w = checkWin(b);
      if (w === 'O') return 10;
      if (w === 'X') return -10;
      if (w === 'T') return 0;
      let best = isMax ? -Infinity : Infinity;
      for (let i = 0; i < 9; i++) {
        if (!b[i]) {
          b[i] = isMax ? 'O' : 'X';
          const v = minimax(b, !isMax);
          b[i] = null;
          best = isMax ? Math.max(best, v) : Math.min(best, v);
        }
      }
      return best;
    };
    // 深度限制 minimax
    const minimaxDepth = (b, isMax, depth, alpha, beta) => {
      const w = checkWin(b);
      if (w === 'O') return 10 - (10 - depth);
      if (w === 'X') return -10 + (10 - depth);
      if (w === 'T' || depth === 0) return 0;
      if (isMax) {
        let best = -Infinity;
        for (let i = 0; i < 9; i++) {
          if (!b[i]) {
            b[i] = 'O';
            const v = minimaxDepth(b, false, depth - 1, alpha, beta);
            b[i] = null;
            best = Math.max(best, v);
            alpha = Math.max(alpha, v);
            if (beta <= alpha) break;
          }
        }
        return best;
      } else {
        let best = Infinity;
        for (let i = 0; i < 9; i++) {
          if (!b[i]) {
            b[i] = 'X';
            const v = minimaxDepth(b, true, depth - 1, alpha, beta);
            b[i] = null;
            best = Math.min(best, v);
            beta = Math.min(beta, v);
            if (beta <= alpha) break;
          }
        }
        return best;
      }
    };
    function aiPick() {
      const diff = diffEl.value;
      const empties = board.map((v, i) => v ? -1 : i).filter(i => i >= 0);
      if (diff === 'easy') {
        // 50% 随机，50% 走最优
        if (Math.random() < 0.5) return empties[Math.floor(Math.random() * empties.length)];
        return bestMove();
      }
      if (diff === 'medium') {
        // 深度 2
        let best = -Infinity, bestI = -1;
        for (const j of empties) {
          board[j] = 'O';
          const v = minimaxDepth(board, false, 2, -Infinity, Infinity);
          board[j] = null;
          if (v > best) { best = v; bestI = j; }
        }
        return bestI;
      }
      return bestMove();
    }
    function bestMove() {
      let best = -Infinity, bestI = -1;
      for (let j = 0; j < 9; j++) {
        if (!board[j]) {
          board[j] = 'O';
          const v = minimax(board, false);
          board[j] = null;
          if (v > best) { best = v; bestI = j; }
        }
      }
      return bestI;
    }
    function render() {
      cv.innerHTML = '';
      for (let i = 0; i < 9; i++) {
        const cell = document.createElement('div');
        cell.style.cssText = 'width: 80px; height: 80px; background: #f3f4f6; display: flex; align-items: center; justify-content: center; font-size: 36px; font-weight: 700; cursor: pointer; border-radius: 6px; color: ' + (board[i] === 'X' ? '#2563eb' : '#ef4444') + ';';
        cell.textContent = board[i] || '';
        if (!board[i] && !aiTurn) {
          cell.onclick = () => {
            if (board[i] || checkWin(board)) return;
            board[i] = 'X';
            const w = checkWin(board);
            if (w) { endGame(w); return; }
            aiTurn = true;
            render();
            setTimeout(() => {
              const ai = aiPick();
              if (ai >= 0) board[ai] = 'O';
              const w2 = checkWin(board);
              if (w2) { endGame(w2); return; }
              aiTurn = false;
              render();
            }, 200);
          };
        }
        cv.appendChild(cell);
      }
    }
    function endGame(w) {
      render();
      if (w === 'X') { stats.you++; status.textContent = '🎉 你赢了！'; }
      else if (w === 'O') { stats.ai++; status.textContent = 'AI 赢了！'; }
      else { stats.draw++; status.textContent = '平局！'; }
      document.getElementById('ot08_youWins').textContent = stats.you;
      document.getElementById('ot08_aiWins').textContent = stats.ai;
      document.getElementById('ot08_draws').textContent = stats.draw;
    }
    function reset(firstByAI) {
      board = Array(9).fill(null);
      aiTurn = !!firstByAI;
      status.textContent = aiTurn ? 'AI 思考中...' : '你（X）vs AI（O）。你下。';
      render();
      if (aiTurn) setTimeout(() => {
        const ai = aiPick();
        if (ai >= 0) board[ai] = 'O';
        aiTurn = false;
        render();
      }, 300);
    }
    document.getElementById('ot08_reset').onclick = () => reset(false);
    document.getElementById('ot08_first').onclick = () => reset(true);
    reset(false);
  }

(h) => {
    h.innerHTML = `<div class="row"><label>选杯 <input type="number" id="ot09_pick" value="0" min="0" max="2"></label><label>主持人提示 <input type="number" id="ot09_hint" value="1" min="0" max="2"></label><button class="primary" id="ot09_run">更新概率</button></div><div id="ot09_out" class="sequence" style="margin-top:12px;"></div>`;
    document.getElementById('ot09_run').onclick = () => {
      const pick = +document.getElementById('ot09_pick').value;
      const hint = +document.getElementById('ot09_hint').value;
      if (hint === pick) { document.getElementById('ot09_out').textContent = '主持人不能指出你选的那杯！'; return; }
      // 球在 0/1/2 的先验 = 1/3
      // P(hint=i | ball=j) = ?
      const pHint = [0, 0, 0];
      for (let ball = 0; ball < 3; ball++) {
        if (ball === pick) pHint[ball] = 0; // 你已经选了，不提示
        else if (ball === hint) pHint[ball] = 0.5; // 主持人指向真球所在的杯 0.5
        else pHint[ball] = 0.5; // 主持人指向空杯
      }
      // 归一化
      const sum = pHint[0] + pHint[1] + pHint[2];
      const probs = pHint.map(p => p / sum);
      document.getElementById('ot09_out').innerHTML = `选了 ${pick}，主持人提示 ${hint}<br>球在 0/1/2 的后验：<br>${probs.map((p, i) => `杯 ${i}: ${(p * 100).toFixed(1)}%`).join(' · ')}<br><br>最佳策略：<strong>改选 ${probs.indexOf(Math.max(...probs))}</strong>`;
    };
  }

(h) => {
    h.innerHTML = `<div class="row"><label>大小 n <input type="number" id="ot10_n" value="20" min="5" max="40"></label><label>速度 <input type="number" id="ot10_sp" value="100" min="20" max="500"></label><button class="primary" id="ot10_start">开始</button><button class="ghost" id="ot10_stop">停</button><button class="ghost" id="ot10_reset">重置</button></div><canvas id="ot10_cv" width="400" height="400" style="margin-top:12px; max-width:100%; border:1px solid var(--line); border-radius: 6px;"></canvas>`;
    let grid = [], n = 20, timer = null;
    const cv = document.getElementById('ot10_cv');
    const ctx = cv.getContext('2d');
    const init = () => {
      n = +document.getElementById('ot10_n').value;
      grid = Array.from({ length: n }, () => Array.from({ length: n }, () => Math.random() < 0.3 ? 1 : 0));
      draw();
    };
    const draw = () => {
      const cell = 400 / n;
      ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, 400, 400);
      ctx.fillStyle = '#1e40af';
      for (let r = 0; r < n; r++) for (let c = 0; c < n; c++) if (grid[r][c]) ctx.fillRect(c * cell, r * cell, cell - 1, cell - 1);
    };
    const step = () => {
      const next = Array.from({ length: n }, () => new Array(n).fill(0));
      for (let r = 0; r < n; r++) for (let c = 0; c < n; c++) {
        let n1 = 0;
        for (let dr = -1; dr <= 1; dr++) for (let dc = -1; dc <= 1; dc++) {
          if (dr === 0 && dc === 0) continue;
          const nr = (r + dr + n) % n, nc = (c + dc + n) % n;
          n1 += grid[nr][nc];
        }
        if (grid[r][c]) next[r][c] = (n1 === 2 || n1 === 3) ? 1 : 0;
        else next[r][c] = (n1 === 3) ? 1 : 0;
      }
      grid = next;
      draw();
    };
    document.getElementById('ot10_start').onclick = () => {
      if (timer) clearInterval(timer);
      const sp = +document.getElementById('ot10_sp').value;
      timer = setInterval(step, sp);
    };
    document.getElementById('ot10_stop').onclick = () => { if (timer) clearInterval(timer); };
    document.getElementById('ot10_reset').onclick = () => { if (timer) clearInterval(timer); init(); };
    init();
  }
